import{_ as e,c as r,o as h,af as i}from"./chunks/framework.BKeRpnBD.js";const p=JSON.parse('{"title":"大畜","description":"焦氏易林注 - 大畜","frontmatter":{"title":"大畜","description":"焦氏易林注 - 大畜"},"headers":[],"relativePath":"classics/jiaoyilin/026.md","filePath":"classics/jiaoyilin/026.md"}'),l={name:"classics/jiaoyilin/026.md"};function n(d,a,t,o,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="大畜" tabindex="-1">大畜 <a class="header-anchor" href="#大畜" aria-label="Permalink to “大畜”">​</a></h1><h3 id="大畜-1" tabindex="-1">大畜 <a class="header-anchor" href="#大畜-1" aria-label="Permalink to “大畜”">​</a></h3><h3 id="大畜之乾" tabindex="-1">大畜之乾 <a class="header-anchor" href="#大畜之乾" aria-label="Permalink to “大畜之乾”">​</a></h3><h3 id="林辭" tabindex="-1">林辭 <a class="header-anchor" href="#林辭" aria-label="Permalink to “林辭”">​</a></h3><p>金柱鐵關，堅固衛災。君子居之，安無憂危。</p><h3 id="注" tabindex="-1">注 <a class="header-anchor" href="#注" aria-label="Permalink to “注”">​</a></h3><p>此全用《大畜》象。艮為金鐵，震為柱，艮為關、為堅固、為君子、為居。○堅，汲古作膠，危作疑，茲依宋元本。</p><h3 id="大畜之坤" tabindex="-1">大畜之坤 <a class="header-anchor" href="#大畜之坤" aria-label="Permalink to “大畜之坤”">​</a></h3><h3 id="林辭-1" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-1" aria-label="Permalink to “林辭”">​</a></h3><p>轉禍為福，喜來入屋。春城夏國，可以飲食，保全家室。</p><h3 id="注-1" tabindex="-1">注 <a class="header-anchor" href="#注-1" aria-label="Permalink to “注”">​</a></h3><p>《大畜》震喜艮屋，兌悅，故喜來入屋。艮為城、為國，震為春，故曰春城。艮納丙，故曰夏國。兌為飲食，艮為室家，艮為守，故室家可保。</p><h3 id="大畜之屯" tabindex="-1">大畜之屯 <a class="header-anchor" href="#大畜之屯" aria-label="Permalink to “大畜之屯”">​</a></h3><h3 id="林辭-2" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-2" aria-label="Permalink to “林辭”">​</a></h3><p>水暴橫行，浮屋壞牆。泱泱溢溢，市師驚惶。止不殆，與母相保。</p><h3 id="注-2" tabindex="-1">注 <a class="header-anchor" href="#注-2" aria-label="Permalink to “注”">​</a></h3><p>居坎坤皆為水，故曰橫行。艮為屋、為牆，艮在上，故曰浮屋，坎破故曰壞牆。坤為師，震為驚惶，伏巽為市，艮為居止，坤為母。</p><h3 id="大畜之蒙" tabindex="-1">大畜之蒙 <a class="header-anchor" href="#大畜之蒙" aria-label="Permalink to “大畜之蒙”">​</a></h3><h3 id="林辭-3" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-3" aria-label="Permalink to “林辭”">​</a></h3><p>虎豹熊罷，遊戲山隅。得其所欲，君子無憂。</p><h3 id="注-3" tabindex="-1">注 <a class="header-anchor" href="#注-3" aria-label="Permalink to “注”">​</a></h3><p>艮為虎豹熊罷。震為遊戲，在艮下故曰山隅。艮為君子，坎為憂，震解故無憂。○各本下有&quot;旅人失利，市空無人&quot;二句，與上吉凶不類，斷為衍文刪。</p><h3 id="大畜之需" tabindex="-1">大畜之需 <a class="header-anchor" href="#大畜之需" aria-label="Permalink to “大畜之需”">​</a></h3><h3 id="林辭-4" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-4" aria-label="Permalink to “林辭”">​</a></h3><p>躬禮履仁，尚德止訟。宗邑以安，三百無患。</p><h3 id="注-4" tabindex="-1">注 <a class="header-anchor" href="#注-4" aria-label="Permalink to “注”">​</a></h3><p>乾為仁，伏坤為躬、為禮。天水《訟》、《需》坎水下降，乾陽上升，陰陽交故止訟。乾為百，離卦數三，故曰三百。坎為患。丁雲：&quot;齊管仲奪伯氏駢邑三百，沒齒無怨&quot;，林或指此。○禮，宋元本作體，依汲古。以，汲古作已，百作伯，茲依宋元本。</p><h3 id="大畜之訟" tabindex="-1">大畜之訟 <a class="header-anchor" href="#大畜之訟" aria-label="Permalink to “大畜之訟”">​</a></h3><h3 id="林辭-5" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-5" aria-label="Permalink to “林辭”">​</a></h3><p>江淮易服，玄黃朱飾。靈公夏徵，衷衵無極。高位崩顛，失其寵室。</p><h3 id="注-5" tabindex="-1">注 <a class="header-anchor" href="#注-5" aria-label="Permalink to “注”">​</a></h3><p>對《明夷》。坤坎皆為水，故曰江淮。震為玄黃，坎為赤，故曰朱飾。震為公、為神，故曰靈公。離為夏，震為衣，坎伏，故曰衷衵。衵，褻衣，衷，懷也。艮為位、為室，艮覆故曰崩、曰失。○衷衵，宋元本作哀相，汲古作哀禍，顧千里曰哀相乃衷衵之訛，《左傳宣九年》：&quot;陳靈公與孔寧、儀行父通夏姬，皆衷其衵，徵舒恥之，射殺靈公&quot;。衵，音日。</p><h3 id="大畜之師" tabindex="-1">大畜之師 <a class="header-anchor" href="#大畜之師" aria-label="Permalink to “大畜之師”">​</a></h3><h3 id="林辭-6" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-6" aria-label="Permalink to “林辭”">​</a></h3><p>不虞之患，禍至無門。奄忽暴卒，痛傷我心。</p><h3 id="注-6" tabindex="-1">注 <a class="header-anchor" href="#注-6" aria-label="Permalink to “注”">​</a></h3><p>詳《蒙》之《明夷》。</p><h3 id="大畜之比" tabindex="-1">大畜之比 <a class="header-anchor" href="#大畜之比" aria-label="Permalink to “大畜之比”">​</a></h3><h3 id="林辭-7" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-7" aria-label="Permalink to “林辭”">​</a></h3><p>三塗五嶽，去危入室。兇禍不作，桀盜堯服。失其寵福，貴人有疾。</p><h3 id="注-7" tabindex="-1">注 <a class="header-anchor" href="#注-7" aria-label="Permalink to “注”">​</a></h3><p>艮山故曰三塗五嶽，艮數三，坎數五也。坎危在外故曰去危。艮為室，坤為兇禍、為惡，故曰桀。坎為盜、為聖，故曰堯。坤為服也。乾為寵福，乾伏故失。艮為貴，坎為疾，故曰貴人有疾。</p><h3 id="大畜之小畜" tabindex="-1">大畜之小畜 <a class="header-anchor" href="#大畜之小畜" aria-label="Permalink to “大畜之小畜”">​</a></h3><h3 id="林辭-8" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-8" aria-label="Permalink to “林辭”">​</a></h3><p>配合相迎，利之四鄉。昏以為期，明星煌煌。欣喜奭懌，所言得當。</p><h3 id="注-8" tabindex="-1">注 <a class="header-anchor" href="#注-8" aria-label="Permalink to “注”">​</a></h3><p>巽為利，正反巽相合故曰相迎，巽數四，故曰四鄉。伏坤為鄉、為昏，艮為時，故曰昏以為期。離為星、為明，故曰明星煌煌。兌悅故欣喜。奭，盛也。懌，悅也。奭懌，猶大悅也。兌口為言，正反兌故曰得當。○煌煌，宋元本作熠熠，不協。奭懌，宋元作君奭，均依汲古。當，汲古作償，依宋元本。</p><h3 id="大畜之履" tabindex="-1">大畜之履 <a class="header-anchor" href="#大畜之履" aria-label="Permalink to “大畜之履”">​</a></h3><h3 id="林辭-9" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-9" aria-label="Permalink to “林辭”">​</a></h3><p>三手六身，莫適所閑。更相搖動，失事便安。箕子佯狂，國乃不昌。</p><h3 id="注-9" tabindex="-1">注 <a class="header-anchor" href="#注-9" aria-label="Permalink to “注”">​</a></h3><p>伏《謙》。艮為手，數三，故曰三手。坤為身，坎數六，故曰六身。艮為閑，正反艮，故曰莫適所閑，正反震，故曰更相搖動。坤為事，坎為失，失事便安者，言事不得安也。震為箕子、為狂，坤為國，坤喪故不昌。全用旁通。○第四句汲古作動失事宜，依宋元本。</p><h3 id="大畜之泰" tabindex="-1">大畜之泰 <a class="header-anchor" href="#大畜之泰" aria-label="Permalink to “大畜之泰”">​</a></h3><h3 id="林辭-10" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-10" aria-label="Permalink to “林辭”">​</a></h3><p>虎臥山隅，鹿過後朐。弓矢設張，匯為功曹。伏不敢起，遂全其軀，得我美草。</p><h3 id="注-10" tabindex="-1">注 <a class="header-anchor" href="#注-10" aria-label="Permalink to “注”">​</a></h3><p>詳《大有》之《訟》。○匯，宋本作會，會為音訛字，元本、汲古作蝟，蝟即蝟，見《爾雅》。</p><h3 id="大畜之否" tabindex="-1">大畜之否 <a class="header-anchor" href="#大畜之否" aria-label="Permalink to “大畜之否”">​</a></h3><h3 id="林辭-11" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-11" aria-label="Permalink to “林辭”">​</a></h3><p>麟鳳執獲，英雄失職。自衛反魯，猥昧不起，祿福訖已。</p><h3 id="注-11" tabindex="-1">注 <a class="header-anchor" href="#注-11" aria-label="Permalink to “注”">​</a></h3><p>坤為文，故曰麟鳳。艮為拘，故曰執獲。乾為英雄，巽隕落故失職。伏震為衛、為及，兌為魯，又為昧。猥，曲也，坤死故曰不起、曰訖已。乾為祿福。《公羊傳哀十四年》：&quot;獲麟，孔子觀之，反袂掩泣，自傷將死&quot;。○英，宋元本作陰，依汲古。猥，汲古作畏，祿福作福祿，均依宋元。</p><h3 id="大畜之同人" tabindex="-1">大畜之同人 <a class="header-anchor" href="#大畜之同人" aria-label="Permalink to “大畜之同人”">​</a></h3><h3 id="林辭-12" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-12" aria-label="Permalink to “林辭”">​</a></h3><p>欒子作殃，伯氏誅傷。州犂奔楚，失其寵光。</p><h3 id="注-12" tabindex="-1">注 <a class="header-anchor" href="#注-12" aria-label="Permalink to “注”">​</a></h3><p>《左傳成十五年》：&quot;晉三卻害伯宗，譖而殺之，及欒弗忌，伯州犂奔楚&quot;。卦通《師》。震為木、為子，故曰欒子。為伯、為楚、為奔，坤死故曰殃、曰誅、曰失。</p><h3 id="大畜之大有" tabindex="-1">大畜之大有 <a class="header-anchor" href="#大畜之大有" aria-label="Permalink to “大畜之大有”">​</a></h3><h3 id="林辭-13" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-13" aria-label="Permalink to “林辭”">​</a></h3><p>黃帝出遊，駕龍乘馬。東至泰山，南過齊魯。王良御右，文武何咎。</p><h3 id="注-13" tabindex="-1">注 <a class="header-anchor" href="#注-13" aria-label="Permalink to “注”">​</a></h3><p>不利市賈。此用《大畜》象。震為黃，乾為帝、為行，故曰出遊。乾為龍馬，震為東，艮為山，故東至泰山。乾為南，兌為魯，伏巽為齊，故南過齊魯。乾為王，兌為右，伏坤為文，巽為市賈，巽伏故不利。○乘，宋元本作騎，右作左，今依汲古。</p><h3 id="大畜之謙" tabindex="-1">大畜之謙 <a class="header-anchor" href="#大畜之謙" aria-label="Permalink to “大畜之謙”">​</a></h3><h3 id="林辭-14" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-14" aria-label="Permalink to “林辭”">​</a></h3><p>齊魯爭言，戰於龍門。遘怨致禍，三世不安。</p><h3 id="注-14" tabindex="-1">注 <a class="header-anchor" href="#注-14" aria-label="Permalink to “注”">​</a></h3><p>詳《坤》之《離》。齊魯用伏象。</p><h3 id="大畜之豫" tabindex="-1">大畜之豫 <a class="header-anchor" href="#大畜之豫" aria-label="Permalink to “大畜之豫”">​</a></h3><h3 id="林辭-15" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-15" aria-label="Permalink to “林辭”">​</a></h3><p>道禮和德，仁不相賊。君子往之，樂有其利。</p><h3 id="注-15" tabindex="-1">注 <a class="header-anchor" href="#注-15" aria-label="Permalink to “注”">​</a></h3><p>震為道，坤為禮，坎為和、為賊，震為仁，故不相賊。震為樂，艮為君子。○禮，元本作理，茲依宋本、汲古。</p><h3 id="大畜之隨" tabindex="-1">大畜之隨 <a class="header-anchor" href="#大畜之隨" aria-label="Permalink to “大畜之隨”">​</a></h3><h3 id="林辭-16" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-16" aria-label="Permalink to “林辭”">​</a></h3><p>嫗妬公妮，毀益亂類。使我家憒，利得不遂。</p><h3 id="注-16" tabindex="-1">注 <a class="header-anchor" href="#注-16" aria-label="Permalink to “注”">​</a></h3><p>巽為嫗，震為公，兌為毀，艮為家，巽為利。妮者，泥也，滯也。《論語》：&quot;致遠恐泥&quot;，公泥者，公怠於事也，有此二因致家事毀亂，利得不遂也。○妮，從元本，疑為怩訛，宋本、汲古作姥。類，宋元本作賴，依汲古。利得不遂，汲古作利不得遂，依宋元本。憒，汲古作憤，依宋元本。</p><h3 id="大畜之蠱" tabindex="-1">大畜之蠱 <a class="header-anchor" href="#大畜之蠱" aria-label="Permalink to “大畜之蠱”">​</a></h3><h3 id="林辭-17" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-17" aria-label="Permalink to “林辭”">​</a></h3><p>一巢九子，同公共母。柔順利貞，出入不殆，福祿所在。</p><h3 id="注-17" tabindex="-1">注 <a class="header-anchor" href="#注-17" aria-label="Permalink to “注”">​</a></h3><p>艮為巢，坎數一，故曰一巢，震為子，數九，故曰九子。震為公，巽為母、為柔順、為利、為入，震為福祿、為出。○出入，汲古作君子，依宋元本。</p><h3 id="大畜之臨" tabindex="-1">大畜之臨 <a class="header-anchor" href="#大畜之臨" aria-label="Permalink to “大畜之臨”">​</a></h3><h3 id="林辭-18" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-18" aria-label="Permalink to “林辭”">​</a></h3><p>崔崽北嶽，天神貴客。溫仁正直，主布恩德。閔哀不已，蒙受大福。</p><h3 id="注-18" tabindex="-1">注 <a class="header-anchor" href="#注-18" aria-label="Permalink to “注”">​</a></h3><p>詳《師》之《豐》。</p><h3 id="大畜之觀" tabindex="-1">大畜之觀 <a class="header-anchor" href="#大畜之觀" aria-label="Permalink to “大畜之觀”">​</a></h3><h3 id="林辭-19" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-19" aria-label="Permalink to “林辭”">​</a></h3><p>三蛆逐蠅，陷墮釜中。灌沸渰殪，與母長訣。</p><h3 id="注-19" tabindex="-1">注 <a class="header-anchor" href="#注-19" aria-label="Permalink to “注”">​</a></h3><p>巽為蛆蠅，艮數三，故曰三蛆。巽為墮，坤為釜、為母、為死，故渰殪。○蛆，宋元本作睢，依汲古。</p><h3 id="大畜之噬嗑" tabindex="-1">大畜之噬嗑 <a class="header-anchor" href="#大畜之噬嗑" aria-label="Permalink to “大畜之噬嗑”">​</a></h3><h3 id="林辭-20" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-20" aria-label="Permalink to “林辭”">​</a></h3><p>東山西陵，高峻難升。滅夷掘壘，使道不通。商旅無功，復反其邦。</p><h3 id="注-20" tabindex="-1">注 <a class="header-anchor" href="#注-20" aria-label="Permalink to “注”">​</a></h3><p>艮為山陵，離東坎西，故曰東山西陵。艮為高陵，坎險，故難升。坎為平，故曰滅夷。艮為壘，艮手為掘、為道、為邦，震為商旅、為反，坎陷坎險，居中爻，故道不通而商旅困也。○掘壘，元本作握累，依宋、汲古本。</p><h3 id="大畜之賁" tabindex="-1">大畜之賁 <a class="header-anchor" href="#大畜之賁" aria-label="Permalink to “大畜之賁”">​</a></h3><h3 id="林辭-21" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-21" aria-label="Permalink to “林辭”">​</a></h3><p>常德自如，不逢禍災。樂只君子，福祿自來。</p><h3 id="注-21" tabindex="-1">注 <a class="header-anchor" href="#注-21" aria-label="Permalink to “注”">​</a></h3><p>坎為禍災，震出故不逢。艮為君子，震為樂、為福祿。</p><h3 id="大畜之剝" tabindex="-1">大畜之剝 <a class="header-anchor" href="#大畜之剝" aria-label="Permalink to “大畜之剝”">​</a></h3><h3 id="林辭-22" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-22" aria-label="Permalink to “林辭”">​</a></h3><p>範子妙材，戮辱傷膚。後相秦國，封為應侯。</p><h3 id="注-22" tabindex="-1">注 <a class="header-anchor" href="#注-22" aria-label="Permalink to “注”">​</a></h3><p>詳《師》之《井》。</p><h3 id="大畜之復" tabindex="-1">大畜之復 <a class="header-anchor" href="#大畜之復" aria-label="Permalink to “大畜之復”">​</a></h3><h3 id="林辭-23" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-23" aria-label="Permalink to “林辭”">​</a></h3><p>虎狼結集，相聚為保。伺嚙牛羊，道絕不通。病我商人。</p><h3 id="注-23" tabindex="-1">注 <a class="header-anchor" href="#注-23" aria-label="Permalink to “注”">​</a></h3><p>此用《大畜》象。艮為虎狼，正反艮，艮止，故曰虎狼結集，相聚為保。伏坤為牛，兌為羊、為口，艮止，故曰伺嚙牛羊。艮為道，震為商人，艮止故道不通而商旅困也。○集，汲古作謀，保作儔，伺訛同，均依宋元本。</p><h3 id="大畜之無妄" tabindex="-1">大畜之無妄 <a class="header-anchor" href="#大畜之無妄" aria-label="Permalink to “大畜之無妄”">​</a></h3><h3 id="林辭-24" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-24" aria-label="Permalink to “林辭”">​</a></h3><p>不直杜公，與我爭訟。媒伯無禮，自令壅塞。</p><h3 id="注-24" tabindex="-1">注 <a class="header-anchor" href="#注-24" aria-label="Permalink to “注”">​</a></h3><p>震為杜、為公，杜公，未詳所指。初至四正反震，故曰爭訟。震為伯。○直，汲古作宜，從宋元本。杜公，疑即杜伯，周宣王殺之，非其罪，即為人見王訴其無罪，後射死宣王於鎬，事見《周語》及《周春秋》。媒伯無禮者，言王妾以無禮之事媒孽杜伯而王不知也。</p><h3 id="大畜之大畜" tabindex="-1">大畜之大畜 <a class="header-anchor" href="#大畜之大畜" aria-label="Permalink to “大畜之大畜”">​</a></h3><h3 id="林辭-25" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-25" aria-label="Permalink to “林辭”">​</a></h3><p>朝鮮之地，箕伯所保。宜人宜家，叢處子孫，求事大吉。</p><h3 id="注-25" tabindex="-1">注 <a class="header-anchor" href="#注-25" aria-label="Permalink to “注”">​</a></h3><p>震為朝，艮在東北，故曰朝鮮。伏坤為地，震為箕、為伯、為人，艮為家、為子孫、為求。《後漢書》：&quot;箕子封朝鮮，教以禮義，其人終不相盜，無門戶之閉&quot;。○箕伯，汲古作姫伯，依宋元本。</p><h3 id="大畜之頤" tabindex="-1">大畜之頤 <a class="header-anchor" href="#大畜之頤" aria-label="Permalink to “大畜之頤”">​</a></h3><h3 id="林辭-26" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-26" aria-label="Permalink to “林辭”">​</a></h3><p>上天樓臺，登拜受福，喜慶大來。</p><h3 id="注-26" tabindex="-1">注 <a class="header-anchor" href="#注-26" aria-label="Permalink to “注”">​</a></h3><p>艮為天，坤為樓臺，艮為拜，震為登、為喜。○拜，宋元本作降，大作自，茲依汲古。</p><h3 id="大畜之大過" tabindex="-1">大畜之大過 <a class="header-anchor" href="#大畜之大過" aria-label="Permalink to “大畜之大過”">​</a></h3><h3 id="林辭-27" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-27" aria-label="Permalink to “林辭”">​</a></h3><p>三羊上山，東至平原。黃龍服箱，南至魯陽。完其佩囊，執綏車中，行人有慶。</p><h3 id="注-27" tabindex="-1">注 <a class="header-anchor" href="#注-27" aria-label="Permalink to “注”">​</a></h3><p>伏《頤》。震為羊，艮為山，數三，故曰三羊上山。震為東，坤為平原，震為黃龍、為箱、為南，兌為魯，魯陽，在南陽郡。坤為囊、為車，巽為綏，震為行人。○原，汲古作康，依宋元本。宋元本完作貌，佩作佩，綏訛綬，有慶作無功，均依汲古。</p><h3 id="大畜之坎" tabindex="-1">大畜之坎 <a class="header-anchor" href="#大畜之坎" aria-label="Permalink to “大畜之坎”">​</a></h3><h3 id="林辭-28" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-28" aria-label="Permalink to “林辭”">​</a></h3><p>天地閉塞，仁智隱伏。商旅不行，利深難得。</p><h3 id="注-28" tabindex="-1">注 <a class="header-anchor" href="#注-28" aria-label="Permalink to “注”">​</a></h3><p>艮為天，坎為閉塞，震為仁，坎為智、為隱伏，故曰仁智隱伏。震為商旅、為行，巽為利，巽伏故曰難得。</p><h3 id="大畜之離" tabindex="-1">大畜之離 <a class="header-anchor" href="#大畜之離" aria-label="Permalink to “大畜之離”">​</a></h3><h3 id="林辭-29" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-29" aria-label="Permalink to “林辭”">​</a></h3><p>延陵適魯，觀樂太史。車轔白顛，知秦興起。卒兼其國，一統為主。</p><h3 id="注-29" tabindex="-1">注 <a class="header-anchor" href="#注-29" aria-label="Permalink to “注”">​</a></h3><p>兼用對象。坎艮為少男，故曰延陵。延陵，季子也。兌為魯，震為樂，離為觀。太史者，掌樂之官，觀樂太史，言觀樂於太史也。震為車、為的顙，故曰白顛。兌為秦，震為興起，艮為國，正覆艮，故兼其國。震為主，坎數一，言秦兼併六國，一統天下也。轔，與毛詩異，全用吳季札在魯觀樂事。</p><h3 id="大畜之鹹" tabindex="-1">大畜之鹹 <a class="header-anchor" href="#大畜之鹹" aria-label="Permalink to “大畜之鹹”">​</a></h3><h3 id="林辭-30" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-30" aria-label="Permalink to “林辭”">​</a></h3><p>櫜戢甲兵，歸放馬牛。徑路開通，國無兇憂。</p><h3 id="注-30" tabindex="-1">注 <a class="header-anchor" href="#注-30" aria-label="Permalink to “注”">​</a></h3><p>艮為甲兵，艮止故橐戢，互乾為馬，艮為牛、為徑路，艮為國，震樂故無憂。</p><h3 id="大畜之恆" tabindex="-1">大畜之恆 <a class="header-anchor" href="#大畜之恆" aria-label="Permalink to “大畜之恆”">​</a></h3><h3 id="林辭-31" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-31" aria-label="Permalink to “林辭”">​</a></h3><p>牛驥同槽，郭氏以亡。國破為墟，主君走逃。</p><h3 id="注-31" tabindex="-1">注 <a class="header-anchor" href="#注-31" aria-label="Permalink to “注”">​</a></h3><p>○槽，各本作堂，依《小畜》之《晉》校。主君，各本作君奔，依《豫》之《姤》校。兌為羊，象形故亦為牛，震為馬，故曰牛驥同槽。槽，亦震象。震為主，君在外故曰走逃。</p><h3 id="大畜之遯" tabindex="-1">大畜之遯 <a class="header-anchor" href="#大畜之遯" aria-label="Permalink to “大畜之遯”">​</a></h3><h3 id="林辭-32" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-32" aria-label="Permalink to “林辭”">​</a></h3><p>大尾小腰，重不可搖。棟橈榱壞，臣為君憂。湯火之言，消不為患。使我復安。</p><h3 id="注-32" tabindex="-1">注 <a class="header-anchor" href="#注-32" aria-label="Permalink to “注”">​</a></h3><p>乾為大，艮為尾、為棟榱，巽隕故橈壞。艮為臣，乾為君，遯陽消卦，故臣為君憂。乾為言，艮火在下，故曰湯火之言。湯者，九家、荀爽皆以乾為河，疑乾有水象，有水故不畏火，故曰消不為患。艮止故安。○湯火，元本作陽火，茲依汲古。</p><h3 id="大畜之大壯" tabindex="-1">大畜之大壯 <a class="header-anchor" href="#大畜之大壯" aria-label="Permalink to “大畜之大壯”">​</a></h3><h3 id="林辭-33" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-33" aria-label="Permalink to “林辭”">​</a></h3><p>大一置酒，樂正起舞。萬福攸同，可以安處。綏我齯齒。</p><h3 id="注-33" tabindex="-1">注 <a class="header-anchor" href="#注-33" aria-label="Permalink to “注”">​</a></h3><p>詳《復》之《家人》。</p><h3 id="大畜之晉" tabindex="-1">大畜之晉 <a class="header-anchor" href="#大畜之晉" aria-label="Permalink to “大畜之晉”">​</a></h3><h3 id="林辭-34" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-34" aria-label="Permalink to “林辭”">​</a></h3><p>飲酒醉酗，跳起爭鬬。伯傷叔僵，東家治喪。</p><h3 id="注-34" tabindex="-1">注 <a class="header-anchor" href="#注-34" aria-label="Permalink to “注”">​</a></h3><p>坎為酒，坤迷，故醉。《大畜》正反艮震，故曰爭鬬。震為伯，兌傷，故曰伯傷。艮為叔，艮止，故曰叔僵。震東艮家，皆用遇卦象。</p><h3 id="大畜之明夷" tabindex="-1">大畜之明夷 <a class="header-anchor" href="#大畜之明夷" aria-label="Permalink to “大畜之明夷”">​</a></h3><h3 id="林辭-35" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-35" aria-label="Permalink to “林辭”">​</a></h3><p>山險難登，澗中多石。車馳辝擊，重載傷軸。擔負善躓，跌踒右足。</p><h3 id="注-35" tabindex="-1">注 <a class="header-anchor" href="#注-35" aria-label="Permalink to “注”">​</a></h3><p>詳《乾》之《謙》。○澗，宋元本作渭，均依汲古。</p><h3 id="大畜之家人" tabindex="-1">大畜之家人 <a class="header-anchor" href="#大畜之家人" aria-label="Permalink to “大畜之家人”">​</a></h3><h3 id="林辭-36" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-36" aria-label="Permalink to “林辭”">​</a></h3><p>爭訟不己，更相擊訽。張季弱口，被髪北走。</p><h3 id="注-36" tabindex="-1">注 <a class="header-anchor" href="#注-36" aria-label="Permalink to “注”">​</a></h3><p>詳《訟》之《損》。顧千里雲《明夷》之《臨》作擊訽，與下走韻，當從。各本皆作諮詢，詢，即訽之訛字。按：顧說是也，今從之。○宋元本下多&quot;耳順從心，躬行至仁。不須以兵，天下太平&quot;四句，依汲古。</p><h3 id="大畜之睽" tabindex="-1">大畜之睽 <a class="header-anchor" href="#大畜之睽" aria-label="Permalink to “大畜之睽”">​</a></h3><h3 id="林辭-37" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-37" aria-label="Permalink to “林辭”">​</a></h3><p>心志無良，傷破妄行。觸牆抵壁，不見戶房。先王閉關，商旅委棄。</p><h3 id="注-37" tabindex="-1">注 <a class="header-anchor" href="#注-37" aria-label="Permalink to “注”">​</a></h3><p>坎為心志，兌為傷破，伏艮為牆壁戶房，坎隱故不見。艮為關，坎閉。</p><h3 id="大畜之蹇" tabindex="-1">大畜之蹇 <a class="header-anchor" href="#大畜之蹇" aria-label="Permalink to “大畜之蹇”">​</a></h3><h3 id="林辭-38" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-38" aria-label="Permalink to “林辭”">​</a></h3><p>鷫鴂鴟梟。治成遇災。綏德安家，周公勤勞。</p><h3 id="注-38" tabindex="-1">注 <a class="header-anchor" href="#注-38" aria-label="Permalink to “注”">​</a></h3><p>詳《噬嗑》之《漸》。○鴂，宋元本作夬，依汲古。遇，汲古作御，依宋元本。</p><h3 id="大畜之解" tabindex="-1">大畜之解 <a class="header-anchor" href="#大畜之解" aria-label="Permalink to “大畜之解”">​</a></h3><h3 id="林辭-39" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-39" aria-label="Permalink to “林辭”">​</a></h3><p>清人高子，久屯外野。逍遙不歸，思我慈母。</p><h3 id="注-39" tabindex="-1">注 <a class="header-anchor" href="#注-39" aria-label="Permalink to “注”">​</a></h3><p>詳《賁》之《艮》。</p><h3 id="大畜之損" tabindex="-1">大畜之損 <a class="header-anchor" href="#大畜之損" aria-label="Permalink to “大畜之損”">​</a></h3><h3 id="林辭-40" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-40" aria-label="Permalink to “林辭”">​</a></h3><p>兩虎爭鬬，股創無處。不成仇讎，行解卻去。</p><h3 id="注-40" tabindex="-1">注 <a class="header-anchor" href="#注-40" aria-label="Permalink to “注”">​</a></h3><p>艮為虎，正反艮，故曰兩虎爭鬬。伏巽為股，兌為創，巽伏故曰無處。○股，元本訛服，依汲古。</p><h3 id="大畜之益" tabindex="-1">大畜之益 <a class="header-anchor" href="#大畜之益" aria-label="Permalink to “大畜之益”">​</a></h3><h3 id="林辭-41" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-41" aria-label="Permalink to “林辭”">​</a></h3><p>天女踞床，不成文章。南箕無舌，飯多沙糠。虐眾盜名，雄雞折頸。</p><h3 id="注-41" tabindex="-1">注 <a class="header-anchor" href="#注-41" aria-label="Permalink to “注”">​</a></h3><p>巽為女，艮為天。天女，織女星也。艮為床，坤為文章，震為南、為箕，艮為星。箕，二十八宿星名。艮為沙，巽為糠。《詩小雅》：&quot;跂彼織女，終日七襄。雖則七襄，不成文章。&quot;又：&quot;維南有箕，不可以●揚。&quot; 不●揚故飯多沙糠。坤為眾，巽為盜、為雞，震為雄，艮為頸，巽隕故折。○踞多作摧，依小過之比改。虐眾，宋本作虛象，非，依元本、汲古。</p><h3 id="大畜之夬" tabindex="-1">大畜之夬 <a class="header-anchor" href="#大畜之夬" aria-label="Permalink to “大畜之夬”">​</a></h3><h3 id="林辭-42" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-42" aria-label="Permalink to “林辭”">​</a></h3><p>太子扶蘇，出於遠郊。佞幸成邪，改命生憂。慈母之恩，無路致之。</p><h3 id="注-42" tabindex="-1">注 <a class="header-anchor" href="#注-42" aria-label="Permalink to “注”">​</a></h3><p>通《剝》。艮在上故曰太子。艮手為扶，坤為薪蘇、為郊。乾為言，兌口亦為言，故曰佞。巽為命，兌為反巽，故曰改命，言太子扶蘇遠出備邊，李斯、趙高竟改始皇璽書，殺扶蘇也。《革九四》雲&quot;改命吉&quot;，即謂巽覆也。坤為憂、為母。○出於，元本作走出，依汲古。</p><h3 id="大畜之姤" tabindex="-1">大畜之姤 <a class="header-anchor" href="#大畜之姤" aria-label="Permalink to “大畜之姤”">​</a></h3><h3 id="林辭-43" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-43" aria-label="Permalink to “林辭”">​</a></h3><p>寒暑相推，一明一微。赫赫宗周，光榮滅衰。</p><h3 id="注-43" tabindex="-1">注 <a class="header-anchor" href="#注-43" aria-label="Permalink to “注”">​</a></h3><p>《姤》夏至一陰生消陽，故曰寒暑相推。乾為宗，震為周，震伏，故光滅。</p><h3 id="大畜之萃" tabindex="-1">大畜之萃 <a class="header-anchor" href="#大畜之萃" aria-label="Permalink to “大畜之萃”">​</a></h3><h3 id="林辭-44" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-44" aria-label="Permalink to “林辭”">​</a></h3><p>雞狗相望，仁道篤行。不吠昏明，各安其鄉。周鼎和餌，國富民有，八極蒙佑。</p><h3 id="注-44" tabindex="-1">注 <a class="header-anchor" href="#注-44" aria-label="Permalink to “注”">​</a></h3><p>巽雞艮狗，艮望，兌為吠，坤為鄉、為安。○後三句與前四句不類，象亦不合，疑衍。</p><h3 id="大畜之升" tabindex="-1">大畜之升 <a class="header-anchor" href="#大畜之升" aria-label="Permalink to “大畜之升”">​</a></h3><h3 id="林辭-45" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-45" aria-label="Permalink to “林辭”">​</a></h3><p>窗牖戶房，通利明光。賢知輔聖，仁施大行。家給人足，海內殷昌。</p><h3 id="注-45" tabindex="-1">注 <a class="header-anchor" href="#注-45" aria-label="Permalink to “注”">​</a></h3><p>伏《無妄》。艮為窗牖戶房，震為通利，艮為明光。乾為聖、為仁，艮為家，坤為海。</p><h3 id="大畜之困" tabindex="-1">大畜之困 <a class="header-anchor" href="#大畜之困" aria-label="Permalink to “大畜之困”">​</a></h3><h3 id="林辭-46" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-46" aria-label="Permalink to “林辭”">​</a></h3><p>雨雪三日，鳥獸飢乏。旅人失宜，利不可得。幾言解患，以療紛難，危者復安。</p><h3 id="注-46" tabindex="-1">注 <a class="header-anchor" href="#注-46" aria-label="Permalink to “注”">​</a></h3><p>坎為雨雪，離卦數三，故曰三日。伏艮為鳥獸，離虛故飢。巽為旅人、為利，伏震為言、為解，坎為患、為危，艮為安。多用伏象。○日，汲古作月，幾作機，紛作篤，者作身，均依宋元本。</p><h3 id="大畜之井" tabindex="-1">大畜之井 <a class="header-anchor" href="#大畜之井" aria-label="Permalink to “大畜之井”">​</a></h3><h3 id="林辭-47" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-47" aria-label="Permalink to “林辭”">​</a></h3><p>白鵠銜珠，夜食為明。膏潤優沃，國歲年豐。中子來同，見惡不兇。</p><h3 id="注-47" tabindex="-1">注 <a class="header-anchor" href="#注-47" aria-label="Permalink to “注”">​</a></h3><p>伏震為白鵠、為珠，兌為銜，故曰白鵠銜珠。坎為夜，離為明，坎為膏潤，艮為國，震為年歲。坎為中男，故曰仲子。○歲，疑富之訛。</p><h3 id="大畜之革" tabindex="-1">大畜之革 <a class="header-anchor" href="#大畜之革" aria-label="Permalink to “大畜之革”">​</a></h3><h3 id="林辭-48" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-48" aria-label="Permalink to “林辭”">​</a></h3><p>從豕牽羊，與虎相逢，雖驚不兇。</p><h3 id="注-48" tabindex="-1">注 <a class="header-anchor" href="#注-48" aria-label="Permalink to “注”">​</a></h3><p>兌為羊，巽為豕，互乾為虎，言有羊豕，虎即不咥人。</p><h3 id="大畜之鼎" tabindex="-1">大畜之鼎 <a class="header-anchor" href="#大畜之鼎" aria-label="Permalink to “大畜之鼎”">​</a></h3><h3 id="林辭-49" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-49" aria-label="Permalink to “林辭”">​</a></h3><p>鳧雁啞啞，以水為宅。雌雄相合，心志娛樂，得其所欲。</p><h3 id="注-49" tabindex="-1">注 <a class="header-anchor" href="#注-49" aria-label="Permalink to “注”">​</a></h3><p>詳《大有》之《歸妹》。○宋元本下多&quot;絕其患惡&quot;四字，依汲古。</p><h3 id="大畜之震" tabindex="-1">大畜之震 <a class="header-anchor" href="#大畜之震" aria-label="Permalink to “大畜之震”">​</a></h3><h3 id="林辭-50" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-50" aria-label="Permalink to “林辭”">​</a></h3><p>逐狐平原，水遏我前。深不可涉，暮無所得。</p><h3 id="注-50" tabindex="-1">注 <a class="header-anchor" href="#注-50" aria-label="Permalink to “注”">​</a></h3><p>艮為狐、為震、為逐，坎水艮止，故曰水遏我前。坎為暮、為失，故無得。</p><h3 id="大畜之艮" tabindex="-1">大畜之艮 <a class="header-anchor" href="#大畜之艮" aria-label="Permalink to “大畜之艮”">​</a></h3><h3 id="林辭-51" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-51" aria-label="Permalink to “林辭”">​</a></h3><p>窟室蓬戶，寒賤所處。千里望煙，散渙四方。形體滅亡，下入深淵，終不見君。</p><h3 id="注-51" tabindex="-1">注 <a class="header-anchor" href="#注-51" aria-label="Permalink to “注”">​</a></h3><p>艮為窟室、為戶，互震故曰蓬戶。坎為寒、為煙，震為千里，坎為深淵，震為君，坎隱故不見。</p><h3 id="大畜之漸" tabindex="-1">大畜之漸 <a class="header-anchor" href="#大畜之漸" aria-label="Permalink to “大畜之漸”">​</a></h3><h3 id="林辭-52" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-52" aria-label="Permalink to “林辭”">​</a></h3><p>桀討［當作紂］之主，悖不堪輔。貪榮為人，必定其咎。聚斂積實，野在鄙邑，未得入室。</p><h3 id="注-52" tabindex="-1">注 <a class="header-anchor" href="#注-52" aria-label="Permalink to “注”">​</a></h3><p>離為惡人，故曰桀紂。伏震為主，坎為悖。艮為榮、為邑、為室，坎為聚斂，巽為人。○斂，宋元本作鈠，依汲古。鄙，汲古作都，得入作來我，茲依宋元本。</p><h3 id="大畜之歸妹" tabindex="-1">大畜之歸妹 <a class="header-anchor" href="#大畜之歸妹" aria-label="Permalink to “大畜之歸妹”">​</a></h3><h3 id="林辭-53" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-53" aria-label="Permalink to “林辭”">​</a></h3><p>倉庫盈億，年歲有息。商人流連，雖久有得。陰多陽少，因地就力。</p><h3 id="注-53" tabindex="-1">注 <a class="header-anchor" href="#注-53" aria-label="Permalink to “注”">​</a></h3><p>伏艮為倉庫，坎眾故盈億。震為年歲、為生、為息、為商人，坎陷故流連。</p><h3 id="大畜之豐" tabindex="-1">大畜之豐 <a class="header-anchor" href="#大畜之豐" aria-label="Permalink to “大畜之豐”">​</a></h3><h3 id="林辭-54" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-54" aria-label="Permalink to “林辭”">​</a></h3><p>火山不然，釣鯉失綸。魚不可得，利去我北。</p><h3 id="注-54" tabindex="-1">注 <a class="header-anchor" href="#注-54" aria-label="Permalink to “注”">​</a></h3><p>離火，伏艮故曰火山，兌水在上故曰不然。巽為系，故為釣、為魚、為綸，兌折故失綸，巽隕落，故魚不得而失利也。○火，汲古作泰，依宋元本。《神異經》：&quot;南荒外有火山&quot;。</p><h3 id="大畜之旅" tabindex="-1">大畜之旅 <a class="header-anchor" href="#大畜之旅" aria-label="Permalink to “大畜之旅”">​</a></h3><h3 id="林辭-55" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-55" aria-label="Permalink to “林辭”">​</a></h3><p>童女無媒，不宜動搖。安其室廬，傅母何憂。</p><h3 id="注-55" tabindex="-1">注 <a class="header-anchor" href="#注-55" aria-label="Permalink to “注”">​</a></h3><p>兌少故曰童女。坎為媒，坎伏故無媒，無媒故不宜動。艮為安、為室，巽為母。○宜，汲古作利，依宋元本。室，宋元本作居，依汲古。</p><h3 id="大畜之巽" tabindex="-1">大畜之巽 <a class="header-anchor" href="#大畜之巽" aria-label="Permalink to “大畜之巽”">​</a></h3><h3 id="林辭-56" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-56" aria-label="Permalink to “林辭”">​</a></h3><p>載風雲母，遊觀東海。鼓翼千里，見吾愛子。</p><h3 id="注-56" tabindex="-1">注 <a class="header-anchor" href="#注-56" aria-label="Permalink to “注”">​</a></h3><p>巽為風、為母，此句疑有訛字，或為載風乘雲也。兌為海，伏震故曰遊觀東海，離為觀也。震為翼、為鼓、為千里，兌悅、震子，故曰愛子。</p><h3 id="大畜之兌" tabindex="-1">大畜之兌 <a class="header-anchor" href="#大畜之兌" aria-label="Permalink to “大畜之兌”">​</a></h3><h3 id="林辭-57" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-57" aria-label="Permalink to “林辭”">​</a></h3><p>鶴盜我襦，逃於山隅。不見武跡，使伯心憂。</p><h3 id="注-57" tabindex="-1">注 <a class="header-anchor" href="#注-57" aria-label="Permalink to “注”">​</a></h3><p>伏《艮》。互震為鶴、為衣，坎為盜，艮為山，故逃於山隅。震為武跡。《詩大雅》：&quot;履帝武敏歆&quot;，《傳》：&quot;武，跡也&quot;。震為伯，坎為心、為憂，坎為隱伏，故不見武跡。○武，汲古作其，依宋元本。</p><h3 id="大畜之渙" tabindex="-1">大畜之渙 <a class="header-anchor" href="#大畜之渙" aria-label="Permalink to “大畜之渙”">​</a></h3><h3 id="林辭-58" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-58" aria-label="Permalink to “林辭”">​</a></h3><p>夜視無明，不利遠鄉。閉門塞牖，福為我母。</p><h3 id="注-58" tabindex="-1">注 <a class="header-anchor" href="#注-58" aria-label="Permalink to “注”">​</a></h3><p>坎為夜故不明。艮為視、為鄉、為門戶，坎為閉塞，震為福，巽為母，言夜黯不明，不宜遠行，杜門不出或致福也。○無，汲古作失，依宋元本。</p><h3 id="大畜之節" tabindex="-1">大畜之節 <a class="header-anchor" href="#大畜之節" aria-label="Permalink to “大畜之節”">​</a></h3><h3 id="林辭-59" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-59" aria-label="Permalink to “林辭”">​</a></h3><p>三狗逐兔，於東北路。利以進取，商人有得。</p><h3 id="注-59" tabindex="-1">注 <a class="header-anchor" href="#注-59" aria-label="Permalink to “注”">​</a></h3><p>艮為狗，數三，故曰三狗。震為兔、為逐，艮居東北為路，故曰於東北路。震為進、為商人。○於，宋元本作子，依汲古。北，汲古作門，依宋元本。</p><h3 id="大畜之中孚" tabindex="-1">大畜之中孚 <a class="header-anchor" href="#大畜之中孚" aria-label="Permalink to “大畜之中孚”">​</a></h3><h3 id="林辭-60" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-60" aria-label="Permalink to “林辭”">​</a></h3><p>武王不豫，周公禱謝。載璧秉圭，安寧如故。</p><h3 id="注-60" tabindex="-1">注 <a class="header-anchor" href="#注-60" aria-label="Permalink to “注”">​</a></h3><p>《書金縢》：武王不豫，周公冊祝，植璧秉圭，請以身代，翊日王瘳。震為武、為王、為周、為公、為言，故曰禱。為玉故為圭璧。艮為秉。○載，今書作植，《史記》作戴，未知孰是。</p><h3 id="大畜之小過" tabindex="-1">大畜之小過 <a class="header-anchor" href="#大畜之小過" aria-label="Permalink to “大畜之小過”">​</a></h3><h3 id="林辭-61" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-61" aria-label="Permalink to “林辭”">​</a></h3><p>同載共車，中道別去。爵級不進，君子下輿。</p><h3 id="注-61" tabindex="-1">注 <a class="header-anchor" href="#注-61" aria-label="Permalink to “注”">​</a></h3><p>震為車、為載，艮為道、為反震，故曰別去，言背震別行也。震為樽爵，艮為君子，艮止故不進。古君子方得乘輿，下輿言不仕也。○下輿，宋元本作不，依汲古。</p><h3 id="大畜之既濟" tabindex="-1">大畜之既濟 <a class="header-anchor" href="#大畜之既濟" aria-label="Permalink to “大畜之既濟”">​</a></h3><h3 id="林辭-62" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-62" aria-label="Permalink to “林辭”">​</a></h3><p>六雁俱飛，遊戲稻池。大飲多食，食飽無患。</p><h3 id="注-62" tabindex="-1">注 <a class="header-anchor" href="#注-62" aria-label="Permalink to “注”">​</a></h3><p>坎數六，震為雁、為飛，卦有三半震故曰俱飛。震為遊、為稻，坎為池，兌為飲食。</p><h3 id="大畜之未濟" tabindex="-1">大畜之未濟 <a class="header-anchor" href="#大畜之未濟" aria-label="Permalink to “大畜之未濟”">​</a></h3><h3 id="林辭-63" tabindex="-1">林辭 <a class="header-anchor" href="#林辭-63" aria-label="Permalink to “林辭”">​</a></h3><p>符左契右，相與合齒。乾坤利貞，出生六子。長大成就，風言如母。</p><h3 id="注-63" tabindex="-1">注 <a class="header-anchor" href="#注-63" aria-label="Permalink to “注”">​</a></h3><p>卦一陰一陽相間皆相交，故曰符契、曰合齒。震左兌右，兌齒，坎為合也，卦氣至亥陰凝於陽，故曰利貞。《未濟》亥月之卦也，至子則震出矣，故出生六子。○依《兌》之《大過》校刪末句&quot;不利為咎&quot;四字。合齒，宋元本作虐亂。出生，元本作倖生，汲古作季生。風言，宋元本作颯然，皆非。</p>',322)])])}const f=e(l,[["render",n]]);export{p as __pageData,f as default};
